import { getLocale } from "next-intl/server";

import { redirect } from "@/i18n/navigation";

/**
 * `/chat` landing — redirects into a freshly-minted conversation id.
 *
 * No `conversations` row is created here. The row is created lazily
 * by `app/api/chat/route.ts` on the first POST for this id, so
 * visiting `/chat` and then never sending a message leaves nothing
 * behind (ADR-0009: conversations are a persistence concern the route
 * owns, not a page-load side effect).
 */
export default async function ChatIndexPage() {
  const locale = await getLocale();
  redirect({ href: `/chat/${crypto.randomUUID()}`, locale });
}

import type { Metadata } from "next";
import { getTranslations } from "next-intl/server";

import { Chat } from "@/components/chat/chat-panel";
import { ConversationHeader } from "@/components/chat/conversation-header";
import { ConversationSidebar } from "@/components/chat/conversation-sidebar";
import {
  listConversationHistory,
  loadConversationForChat,
} from "@/actions/chat";

export async function generateMetadata(): Promise<Metadata> {
  const t = await getTranslations("chat");
  return { title: t("conversationPage.title") };
}

/**
 * `dynamic = "force-dynamic"`: `loadConversationForChat`/
 * `listConversationHistory` read request-scoped session and workspace
 * state (`requireWorkspace()`, inside `@/actions/chat`), so this page
 * can only ever render per-request.
 */
export const dynamic = "force-dynamic";

interface ConversationPageProps {
  params: Promise<{ id: string; locale: string }>;
}

export default async function ConversationPage({
  params,
}: ConversationPageProps) {
  const { id } = await params;
  const t = await getTranslations("chat");

  const [conversationResult, historyResult] = await Promise.all([
    loadConversationForChat(id),
    listConversationHistory(),
  ]);

  if (!conversationResult.success) {
    return (
      <div className="flex h-full flex-col items-center justify-center gap-2 p-8 text-center">
        <h1 className="text-lg font-semibold">
          {t("conversationPage.unavailableTitle")}
        </h1>
        <p className="text-sm text-muted-foreground">
          {conversationResult.error}
        </p>
      </div>
    );
  }

  const { conversation, messages } = conversationResult.data;
  const conversations = historyResult.success ? historyResult.data : [];
  // The header's dropdown is the small-screen fallback for the
  // sidebar, and there it lists somewhere to go — so the conversation
  // already on screen is filtered out of it, but not out of the
  // sidebar, which highlights it instead.
  const history = conversations.filter((item) => item.id !== id);

  return (
    <div className="flex h-full">
      <ConversationSidebar conversations={conversations} activeId={id} />

      <div className="flex min-w-0 flex-1 flex-col">
        <ConversationHeader
          conversationId={id}
          title={conversation?.title ?? null}
          history={history}
        />
        <Chat conversationId={id} initialMessages={messages} />
      </div>
    </div>
  );
}

import { Skeleton } from "@/components/ui/skeleton";

export default function ConversationLoading() {
  return (
    <div className="flex h-full flex-col">
      <div className="flex items-center justify-between border-b px-4 py-3">
        <Skeleton className="h-5 w-40" />
        <Skeleton className="h-8 w-24" />
      </div>
      <div className="flex-1 space-y-6 px-4 py-6">
        <div className="mx-auto flex max-w-3xl flex-col gap-6">
          <Skeleton className="ml-auto h-10 w-2/3 rounded-2xl" />
          <Skeleton className="h-24 w-3/4 rounded-lg" />
          <Skeleton className="ml-auto h-10 w-1/2 rounded-2xl" />
        </div>
      </div>
    </div>
  );
}

/**
 * Chat API Route Handler.
 *
 * POST — streams an assistant reply through the execution boundary:
 *   auth → rate limit → feature gate → load-or-create conversation →
 *   executions.begin() → streamText → persist. Ordering mirrors
 * Acme's production `/api/chat` route; ADR-0003 is why entitlement
 * is decided here (`executions.begin`) rather than earlier — the hold
 * has to match the model that's actually about to run.
 *
 * Deletion is not handled here: the `deleteConversation` server action
 * in `actions/chat.ts` is the one delete path (the UI already calls
 * it, and a second HTTP surface for the same mutation would just be
 * drift risk).
 *
 * Consumer contract: this route imports `{ composeIntelligo, executions }`
 * from `@/lib/intelligo` — this scaffold's composition root (ADR-0005).
 * `executions` must be an `Executions` instance
 * (`@intelligo-dev/executions`'s `createExecutions(ports)`) with its
 * entitlement/settlement ports already bound to this deployment's
 * billing rules; `composeIntelligo()` must be idempotent and safe to
 * call on every request (Next does not guarantee one module instance
 * across server bundles — see AGENTS.md). If your app names that file
 * or those exports differently, update the import below; nothing else
 * in this route assumes a specific composition-root shape beyond
 * those two names.
 *
 * Everything else this route decides — system prompt, tools, feature
 * key, capability, agent id, message-length cap, step budget, and how a
 * new conversation is titled — comes from `@/lib/chat-server-config`,
 * consumer-owned source you edit instead of this file. Tools in
 * particular: bind them there and the tool-renderer seam in
 * `@/lib/chat-renderers` starts receiving calls.
 *
 * `chatServerConfig.featureKey` ("chat" by default) must be registered
 * for at least one plan via `registerProductFeatures`
 * (`@intelligo-dev/billing/plans`) or every request is feature-gated out —
 * see `@/lib/plans.ts`.
 *
 * i18n: this route lives at `app/api/chat/route.ts`, outside the
 * `[locale]` segment (ADR-0010), so there is no URL segment or
 * `next-intl` middleware header to read a locale from. `resolveLocale`
 * below falls back to the `NEXT_LOCALE` cookie next-intl's middleware
 * already sets for every page navigation, then to the configured
 * default locale — the same "works with nothing extra" guarantee a
 * single-locale deployment gets everywhere else.
 */

import {
  convertToModelMessages,
  createUIMessageStream,
  createUIMessageStreamResponse,
  generateId,
  stepCountIs,
  streamText,
} from "ai";
import type { UIMessage } from "ai";
import { cookies } from "next/headers";
import { getTranslations } from "next-intl/server";
import { z } from "zod";

import { requireWorkspace } from "@intelligo-dev/auth";
import {
  checkRateLimit,
  getWorkspaceBilling,
  hasFeature,
} from "@intelligo-dev/billing";
import {
  createConversation,
  getConversation,
  isConversationServiceError,
  upsertMessages,
} from "@intelligo-dev/core/conversations";
import { createLogger } from "@intelligo-dev/core/logger";

import { routing } from "@/i18n/routing";
import { composeIntelligo, executions } from "@/lib/intelligo";
import { CHAT_MODEL_ID, getChatModel } from "@/lib/chat-model";
import { chatServerConfig } from "@/lib/chat-server-config";

export const maxDuration = 300;

const log = createLogger("ChatRoute");

// ---------------------------------------------------------------------------
// Locale resolution — see the module doc comment's "i18n" section.
// ---------------------------------------------------------------------------

async function resolveLocale(): Promise<string> {
  const cookieName =
    typeof routing.localeCookie === "object"
      ? (routing.localeCookie.name ?? "NEXT_LOCALE")
      : "NEXT_LOCALE";
  const value = (await cookies()).get(cookieName)?.value;
  const locales: readonly string[] = routing.locales;
  return value && locales.includes(value) ? value : routing.defaultLocale;
}

async function chatTranslations() {
  return getTranslations({ locale: await resolveLocale(), namespace: "chat" });
}

// ---------------------------------------------------------------------------
// Request validation
// ---------------------------------------------------------------------------

const messagePartSchema = z.object({ type: z.string() }).passthrough();

const uiMessageSchema = z.object({
  id: z.string(),
  role: z.enum(["system", "user", "assistant"]),
  parts: z.array(messagePartSchema),
});

const postBodySchema = z.object({
  id: z.string().uuid(),
  messages: z.array(uiMessageSchema).min(1),
  trigger: z.string().optional(),
  messageId: z.string().optional(),
});

/**
 * Last user message's combined text length, or `null` if the last
 * message isn't from the user. Split out of `postBodySchema` (rather
 * than a `.superRefine`) because its error message is localized, and a
 * zod refinement has no `await` — `t()` above already needs one.
 */
function lastUserMessageLength(
  body: z.infer<typeof postBodySchema>
): number | null {
  const last = body.messages[body.messages.length - 1];
  if (last?.role !== "user") return null;
  return last.parts
    .filter(
      (part): part is { type: "text"; text: string } =>
        part.type === "text" &&
        typeof (part as { text?: unknown }).text === "string"
    )
    .map((part) => part.text)
    .join("").length;
}

/** Combined text of the first user message — the title source. */
function firstUserText(body: z.infer<typeof postBodySchema>): string {
  const first = body.messages.find((message) => message.role === "user");
  if (!first) return "";
  return first.parts
    .filter(
      (part): part is { type: "text"; text: string } =>
        part.type === "text" &&
        typeof (part as { text?: unknown }).text === "string"
    )
    .map((part) => part.text)
    .join(" ");
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

// ---------------------------------------------------------------------------
// POST — stream a reply
// ---------------------------------------------------------------------------

export async function POST(request: Request) {
  composeIntelligo();
  const t = await chatTranslations();

  let body: z.infer<typeof postBodySchema>;
  try {
    body = postBodySchema.parse(await request.json());
  } catch {
    return Response.json(
      { error: t("route.invalidBody"), code: "BAD_REQUEST" },
      { status: 400 }
    );
  }

  const messageLength = lastUserMessageLength(body);
  if (
    messageLength !== null &&
    messageLength > chatServerConfig.maxMessageLength
  ) {
    return Response.json(
      {
        error: t("route.messageTooLong", {
          max: chatServerConfig.maxMessageLength,
        }),
        code: "BAD_REQUEST",
      },
      { status: 400 }
    );
  }

  let session;
  try {
    session = await requireWorkspace();
  } catch {
    return Response.json(
      { error: t("route.unauthorized"), code: "UNAUTHORIZED" },
      { status: 401 }
    );
  }
  const actor = {
    workspaceId: session.workspace.id,
    userId: session.user.id,
  };

  // Step 1: rate limit.
  const billing = await getWorkspaceBilling(actor.workspaceId);
  const planSlug = billing.plan?.slug ?? "free";
  const rateLimit = await checkRateLimit(actor.workspaceId, planSlug);
  if (!rateLimit.allowed) {
    return Response.json(
      {
        error: t("route.rateLimited", {
          seconds: rateLimit.retryAfterSeconds ?? 60,
        }),
        code: "RATE_LIMITED",
      },
      { status: 429 }
    );
  }

  // Step 2: feature gate.
  const allowed = await hasFeature(
    actor.workspaceId,
    chatServerConfig.featureKey
  );
  if (!allowed) {
    return Response.json(
      {
        error: t("route.featureGated"),
        code: "FEATURE_GATED",
      },
      { status: 403 }
    );
  }

  // Step 3: load-or-create the conversation this turn belongs to.
  try {
    await getConversation(actor, body.id);
  } catch (error) {
    if (isConversationServiceError(error) && error.code === "not_found") {
      try {
        // Title the row from the message that opened it, so history
        // rows are distinguishable without anyone renaming them.
        await createConversation(actor, {
          id: body.id,
          agentId: chatServerConfig.agentId,
          modelId: CHAT_MODEL_ID,
          title: chatServerConfig.deriveTitle(firstUserText(body)),
        });
      } catch (createError) {
        log.error("Failed to create conversation", {
          conversationId: body.id,
          error: errorMessage(createError),
        });
        return Response.json(
          { error: t("route.internalError"), code: "INTERNAL" },
          { status: 500 }
        );
      }
    } else {
      log.error("Failed to load conversation", {
        conversationId: body.id,
        error: errorMessage(error),
      });
      return Response.json(
        { error: t("route.internalError"), code: "INTERNAL" },
        { status: 500 }
      );
    }
  }

  // Step 4: open the execution. Entitlement is decided here, and the
  // worst-case cost reserved, after the model is resolved so the hold
  // matches what will actually run.
  const run = await executions.begin({
    workspaceId: actor.workspaceId,
    userId: actor.userId,
    capability: chatServerConfig.capability,
    model: CHAT_MODEL_ID,
    metadata: { conversationId: body.id },
  });

  if (!run.allowed) {
    return Response.json(
      {
        error: run.reason ?? t("route.quotaExceeded"),
        code: "QUOTA_EXCEEDED",
      },
      { status: 402 }
    );
  }

  // `postBodySchema` validates shape (id/role/a typed part discriminator)
  // without re-declaring every AI SDK part variant — the cast reflects
  // that: parts are zod-validated, just not to the SDK's own exact
  // union type.
  const modelMessages = await convertToModelMessages(
    body.messages as UIMessage[]
  );

  // Captured inside `execute` (where the `streamText` result lives)
  // and read back in the outer `onFinish` below — `result.usage` only
  // resolves once the stream has fully drained.
  let capturedUsage:
    | { inputTokens?: number; outputTokens?: number; totalTokens?: number }
    | undefined;

  // Tools may close over the turn's tenancy (see chat-server-config).
  const tools =
    typeof chatServerConfig.tools === "function"
      ? await chatServerConfig.tools({ ...actor, conversationId: body.id })
      : chatServerConfig.tools;

  const stream = createUIMessageStream({
    execute: async ({ writer }) => {
      const result = streamText({
        model: getChatModel(CHAT_MODEL_ID),
        system: chatServerConfig.systemPrompt,
        messages: modelMessages,
        ...(tools && Object.keys(tools).length > 0
          ? { tools, stopWhen: stepCountIs(chatServerConfig.maxSteps) }
          : {}),
      });

      writer.merge(result.toUIMessageStream());

      const usage = await result.usage;
      capturedUsage = {
        inputTokens: usage?.inputTokens,
        outputTokens: usage?.outputTokens,
        totalTokens: usage?.totalTokens,
      };
    },
    generateId,
    onFinish: async ({ messages: finishedMessages }) => {
      // Settling can throw (unrecorded usage must not be reported as
      // success — see @intelligo-dev/executions). Log and continue so a
      // settlement failure doesn't also cost the user their message
      // history.
      try {
        await run.complete({
          usage: capturedUsage,
          model: CHAT_MODEL_ID,
          metadata: { conversationId: body.id },
        });
      } catch (error) {
        log.error("Execution settlement failed", {
          conversationId: body.id,
          executionId: run.id,
          error: errorMessage(error),
        });
      }

      try {
        await upsertMessages(body.id, finishedMessages);
      } catch (error) {
        log.error("Message persistence failed", {
          conversationId: body.id,
          error: errorMessage(error),
        });
      }
    },
    onError: (error) => {
      // fail() is a no-op if complete() already won, so a late error
      // after a settled stream can't corrupt the row. `t` was already
      // resolved above, before this callback was defined — `onError`
      // itself stays synchronous (the AI SDK does not await it).
      void run.fail({ error });
      return t("route.streamError");
    },
  });

  return createUIMessageStreamResponse({ stream });
}

"use server";

/**
 * Chat conversation actions — thin transport over
 * `@intelligo-dev/core/conversations` (ADR-0009): resolve the caller's actor
 * via `requireWorkspace()`, call the core service, map any
 * `ConversationServiceError` to a friendly message, and reshape the
 * result for the page and its client components. Sending a message and
 * streaming a reply is NOT here — that is `app/api/chat/route.ts`,
 * because streaming needs a Route Handler, not a Server Action.
 *
 * `loadConversationForChat` is the one read that treats `not_found` as
 * success rather than failure: `app/[locale]/(app)/chat/page.tsx`
 * redirects to `/chat/<uuid>` without creating a row (see its doc
 * comment), so the very first render of a brand-new conversation
 * legitimately has no `conversations` row yet — the route handler
 * creates it on the first POST. Every other action here treats
 * `not_found`/`forbidden` as a genuine failure.
 */

import type { UIMessage } from "ai";
import { getTranslations } from "next-intl/server";
import { revalidatePath } from "next/cache";

import { requireWorkspace } from "@intelligo-dev/auth";
import { saveDocument } from "@intelligo-dev/core/documents";
import {
  deleteConversation as deleteConversationRow,
  getConversation,
  getMessages,
  isConversationServiceError,
  listConversations,
  renameConversation as renameConversationRow,
} from "@intelligo-dev/core/conversations";

export type ChatActionResult<T> =
  | { success: true; data: T }
  | { success: false; error: string };

type Translator = Awaited<ReturnType<typeof getTranslations>>;

function friendlyMessageKey(code: string): string | undefined {
  switch (code) {
    case "not_found":
      return "actions.conversationNotFound";
    case "forbidden":
      return "actions.conversationForbidden";
    case "invalid_input":
      return "actions.invalidTitle";
    case "database_error":
      return "actions.databaseError";
    default:
      return undefined;
  }
}

function friendlyError(t: Translator, error: unknown): string {
  // Unknown errors deliberately map to the generic key — a raw
  // `Error#message` can carry internals (SQL, hostnames) to the UI.
  if (isConversationServiceError(error)) {
    const key = friendlyMessageKey(error.code);
    return key ? t(key) : t("actions.genericError");
  }
  return t("actions.genericError");
}

async function actor() {
  const { workspace, user } = await requireWorkspace();
  return { workspaceId: workspace.id, userId: user.id };
}

export type ConversationSummary = {
  id: string;
  title: string | null;
  updatedAt: string;
};

/** Recent conversations for the sidebar and history dropdown, most recently updated first. */
export async function listConversationHistory(): Promise<
  ChatActionResult<ConversationSummary[]>
> {
  try {
    // Enough to fill a sidebar and be worth searching. The cap is
    // deliberate: past a few hundred, filtering belongs in a query,
    // not in the browser (see `conversation-sidebar.tsx`).
    const rows = await listConversations(await actor(), { limit: 100 });
    return {
      success: true,
      data: rows.map((row) => ({
        id: row.id,
        title: row.title,
        updatedAt: row.updatedAt.toISOString(),
      })),
    };
  } catch (error) {
    return {
      success: false,
      error: friendlyError(await getTranslations("chat"), error),
    };
  }
}

function isChatRole(role: string): role is UIMessage["role"] {
  return role === "system" || role === "user" || role === "assistant";
}

/**
 * Stored `messages.parts` is a JSON string (ADR-0009's schema note);
 * a row that fails to parse is dropped rather than crashing the whole
 * conversation load.
 */
function rowToUIMessage(row: {
  id: string;
  role: string;
  parts: string;
}): UIMessage | null {
  if (!isChatRole(row.role)) return null;
  try {
    return { id: row.id, role: row.role, parts: JSON.parse(row.parts) };
  } catch {
    return null;
  }
}

export type LoadedConversation = {
  conversation: { id: string; title: string | null } | null;
  messages: UIMessage[];
};

/**
 * Loads a conversation and its messages for `<Chat>`'s initial state.
 * A conversation id with no row yet resolves as a brand-new, empty
 * chat rather than an error — see the module doc comment above.
 */
export async function loadConversationForChat(
  id: string
): Promise<ChatActionResult<LoadedConversation>> {
  try {
    const scoped = await actor();

    try {
      const conversation = await getConversation(scoped, id);
      const rows = await getMessages(scoped, id);
      return {
        success: true,
        data: {
          conversation: { id: conversation.id, title: conversation.title },
          messages: rows
            .map(rowToUIMessage)
            .filter((m): m is UIMessage => m !== null),
        },
      };
    } catch (error) {
      if (isConversationServiceError(error) && error.code === "not_found") {
        return { success: true, data: { conversation: null, messages: [] } };
      }
      throw error;
    }
  } catch (error) {
    return {
      success: false,
      error: friendlyError(await getTranslations("chat"), error),
    };
  }
}

export async function renameConversation(
  id: string,
  title: string
): Promise<ChatActionResult<{ title: string | null }>> {
  try {
    const updated = await renameConversationRow(await actor(), id, title);
    return { success: true, data: { title: updated.title } };
  } catch (error) {
    return {
      success: false,
      error: friendlyError(await getTranslations("chat"), error),
    };
  }
}

export async function deleteConversation(
  id: string
): Promise<ChatActionResult<undefined>> {
  try {
    await deleteConversationRow(await actor(), id);
    return { success: true, data: undefined };
  } catch (error) {
    return {
      success: false,
      error: friendlyError(await getTranslations("chat"), error),
    };
  }
}

/**
 * Saves one assistant reply as a document artifact, so a useful answer
 * doesn't only live in a conversation. This is the manual counterpart
 * to a `saveArtifact` tool: same destination (`@intelligo-dev/core`'s
 * document persistence, ADR-0009), same `/artifacts` page, just driven
 * by the reader instead of the model.
 *
 * The message id becomes the document id, which makes saving the same
 * reply twice a new *version* of one artifact rather than a duplicate.
 */
export async function saveMessageAsArtifact(params: {
  messageId: string;
  content: string;
  title?: string;
}): Promise<ChatActionResult<{ id: string; title: string }>> {
  const t = await getTranslations("chat");

  const content = params.content.trim();
  if (!content) {
    return { success: false, error: t("actions.emptyArtifact") };
  }

  const title = params.title?.trim() || deriveArtifactTitle(content);

  try {
    const saved = await saveDocument(await actor(), {
      id: params.messageId,
      title,
      content,
      kind: "text",
    });
    revalidatePath("/artifacts");
    return { success: true, data: { id: saved.id, title: saved.title } };
  } catch (error) {
    return { success: false, error: friendlyError(t, error) };
  }
}

const MAX_ARTIFACT_TITLE = 60;

/** First line of the reply, trimmed to something list-sized. */
function deriveArtifactTitle(content: string): string {
  const line =
    content
      .split("\n")
      .map((value) => value.replace(/^#+\s*/, "").trim())
      .find(Boolean) ?? "";
  if (!line) return "Untitled";
  return line.length <= MAX_ARTIFACT_TITLE
    ? line
    : `${line.slice(0, MAX_ARTIFACT_TITLE - 1).trimEnd()}…`;
}

import "server-only";

/**
 * Consumer-owned model resolution for `app/api/chat/route.ts`.
 *
 * A fresh install has no AI provider keys, so `getChatModel` defaults
 * to a deterministic stub: a `MockLanguageModelV3` (from `ai/test`,
 * the AI SDK's own testing surface) that echoes the last user message
 * back through a real token-by-token stream via `simulateReadableStream`.
 * No network call, no API key, and the app still builds, boots, and
 * streams a real `createUIMessageStream` response end to end.
 *
 * `CHAT_MODEL_ID` is deliberately a real, already-registered id
 * (`@intelligo-dev/executions/pricing`'s `MODEL_CONFIGS`) even though the
 * stub never calls that provider: the execution boundary bills
 * whatever id `app/api/chat/route.ts` hands to `run.complete()`
 * (ADR-0003), and an id that isn't in `MODEL_CONFIGS` silently prices
 * at the worst-case Claude rate instead of failing loudly (see
 * AGENTS.md, "Model ids are registry keys"). Using a real id here
 * means a clean install exercises the *correct* pricing path — swap
 * in your own model id the moment you swap in a real provider below,
 * and keep it one that exists in `MODEL_CONFIGS`.
 *
 * To use a real provider: install its AI SDK package (e.g.
 * `pnpm add @ai-sdk/anthropic` in this app) and replace the body of
 * `getChatModel` — the commented example below is the whole change.
 */

import type { LanguageModel } from "ai";
import { MockLanguageModelV3, simulateReadableStream } from "ai/test";
import { cookies } from "next/headers";
import { getTranslations } from "next-intl/server";

import { routing } from "@/i18n/routing";

/**
 * Resolves the caller's locale the same way `app/api/chat/route.ts`
 * does: this file, like that route, lives outside the `[locale]`
 * segment (it's plain server-side utility code, not a page), so there
 * is no URL segment to read a locale from — only the `NEXT_LOCALE`
 * cookie next-intl's middleware already sets on every page navigation.
 * Duplicated here rather than imported from the route: registry items
 * are self-contained (no shared cross-item helper modules), matching
 * `error.tsx`'s "no shared app-internal component" note elsewhere in
 * this item.
 */
async function resolveLocale(): Promise<string> {
  const cookieName =
    typeof routing.localeCookie === "object"
      ? (routing.localeCookie.name ?? "NEXT_LOCALE")
      : "NEXT_LOCALE";
  const value = (await cookies()).get(cookieName)?.value;
  const locales: readonly string[] = routing.locales;
  return value && locales.includes(value) ? value : routing.defaultLocale;
}

/**
 * Structurally matches the AI SDK provider spec's `LanguageModelV3StreamPart`
 * union (only the five variants this stub actually emits) without
 * importing `@ai-sdk/provider` — a transitive dependency of `ai`, not
 * one this item declares. `MockLanguageModelV3.doStream` only checks
 * shape, not the type's name, so a structurally-compatible local type
 * is enough.
 */
type StubStreamPart =
  | { type: "stream-start"; warnings: never[] }
  | { type: "text-start"; id: string }
  | { type: "text-delta"; id: string; delta: string }
  | { type: "text-end"; id: string }
  | {
      type: "finish";
      finishReason: { unified: "stop"; raw: undefined };
      usage: {
        inputTokens: {
          total: number;
          noCache: undefined;
          cacheRead: undefined;
          cacheWrite: undefined;
        };
        outputTokens: { total: number; text: number; reasoning: undefined };
      };
    };

/** Must be a key in `@intelligo-dev/executions/pricing`'s `MODEL_CONFIGS`. */
export const CHAT_MODEL_ID = "google/gemini-2.5-flash";

function lastUserText(
  prompt: readonly { role: string; content: unknown }[]
): string {
  for (let i = prompt.length - 1; i >= 0; i--) {
    const message = prompt[i];
    if (message?.role !== "user") continue;
    const parts = Array.isArray(message.content) ? message.content : [];
    return parts
      .filter(
        (part): part is { type: "text"; text: string } =>
          typeof part === "object" &&
          part !== null &&
          (part as { type?: unknown }).type === "text"
      )
      .map((part) => part.text)
      .join(" ");
  }
  return "";
}

function stubChatModel(): LanguageModel {
  return new MockLanguageModelV3({
    provider: "stub",
    modelId: CHAT_MODEL_ID,
    doStream: async ({ prompt }) => {
      const t = await getTranslations({
        locale: await resolveLocale(),
        namespace: "chat",
      });
      const reply = `${t("stub.preface")}\n\n${t("stub.youSaid")} "${lastUserText(prompt)}"`;
      const words = reply.split(" ");

      const textDeltas: StubStreamPart[] = words.map((word, index) => ({
        type: "text-delta",
        id: "1",
        delta: index === 0 ? word : ` ${word}`,
      }));

      const chunks: StubStreamPart[] = [
        { type: "stream-start", warnings: [] },
        { type: "text-start", id: "1" },
        ...textDeltas,
        { type: "text-end", id: "1" },
        {
          type: "finish",
          finishReason: { unified: "stop", raw: undefined },
          usage: {
            inputTokens: {
              total: Math.max(1, Math.ceil(JSON.stringify(prompt).length / 4)),
              noCache: undefined,
              cacheRead: undefined,
              cacheWrite: undefined,
            },
            outputTokens: {
              total: words.length,
              text: words.length,
              reasoning: undefined,
            },
          },
        },
      ];

      return {
        stream: simulateReadableStream({ chunkDelayInMs: 15, chunks }),
      };
    },
  });
}

/**
 * Resolves the language model for a chat turn. `modelId` is threaded
 * through unused by the stub (it only ever returns one model) — a
 * real implementation switches on it, e.g.:
 *
 *   import { anthropic } from "@ai-sdk/anthropic";
 *
 *   export function getChatModel(modelId: string): LanguageModel {
 *     if (modelId === CHAT_MODEL_ID) return anthropic("claude-sonnet-4-6-20260214");
 *     return anthropic("claude-sonnet-4-6-20260214");
 *   }
 *
 * and `CHAT_MODEL_ID` above becomes whatever `MODEL_CONFIGS` key
 * matches the provider model string you pass.
 */
export function getChatModel(modelId: string): LanguageModel {
  void modelId;
  return stubChatModel();
}

"use client";

/**
 * Tool-call renderer seam.
 *
 * `@intelligo-dev/chat`'s dissolving package (ADR-0008) kept a runtime
 * `Map` that a product registered into at client bootstrap — a
 * package-level registry a consumer could never see, let alone edit.
 * This item's replacement is the opposite of clever: `TOOL_RENDERERS`
 * below is a plain object literal in source you own. Add a tool name
 * → component entry to it directly; there is no `register()` call to
 * invoke from a composition root, and nothing here runs as an import
 * side effect, so ADR-0005 has nothing to enforce against this file.
 *
 * A tool with no entry falls back to `DefaultToolCard`: a generic
 * collapsible view of the tool's raw input/output JSON. It exists so
 * a new tool call always renders *something* honest while you're
 * wiring up its real card — it is not meant to be your product's
 * shipped UI for that tool.
 *
 * `components/chat/message.tsx` calls `getToolRenderer(toolName)` for
 * every `tool-*`/`dynamic-tool` part it renders.
 */

import { type ComponentType, useState } from "react";
import { useTranslations } from "next-intl";
import { ChevronDown, ChevronRight, FileText, Wrench } from "lucide-react";

import { Link } from "@/i18n/navigation";

/**
 * Mirrors the AI SDK's `ToolUIPart`/`DynamicToolUIPart` state union
 * (`ai`'s `dist/index.d.ts`) structurally rather than importing it, so
 * this file doesn't pin a consumer to the SDK's exact tool-generics
 * shape. The three `approval-*`/`output-denied` states only appear for
 * tools using the SDK's human-in-the-loop approval flow — a plain tool
 * never produces them.
 */
export type ToolPartState =
  | "input-streaming"
  | "input-available"
  | "approval-requested"
  | "approval-responded"
  | "output-available"
  | "output-error"
  | "output-denied";

/**
 * What a renderer can do back to the conversation. Passed to every
 * renderer, so an *interactive* tool card — approve/deny, pick one of
 * several options, submit a form the tool asked for — is possible
 * without reaching around the component tree.
 *
 * `addToolResult` answers the tool call the card is rendering (pass
 * its `toolCallId`); `sendMessage` sends a new user turn instead.
 */
export interface ToolRendererActions {
  sendMessage: (text: string) => void;
  addToolResult: (args: {
    tool: string;
    toolCallId: string;
    output: unknown;
  }) => void;
}

export interface ToolRendererProps {
  toolName: string;
  state: ToolPartState;
  input?: unknown;
  output?: unknown;
  errorText?: string;
  /** The AI SDK's id for this call — required by `addToolResult`. */
  toolCallId?: string;
  /** Present when the message list passes them; see above. */
  actions?: ToolRendererActions;
}

/**
 * Map of AI SDK tool name → the component that renders its call and
 * result.
 *
 * Ships with one entry: `saveArtifact`, the convention this catalogue
 * uses for "the assistant produced a document." Bind a tool of that
 * name in `@/lib/chat-server-config` and its result renders as a card
 * linking into the `artifacts` page. Rename the key if your tool is
 * called something else.
 *
 * Add your own the same way — this is a plain object literal in source
 * you own, with no `register()` call anywhere:
 *
 *   import { WeatherCard } from "@/components/chat/weather-card";
 *
 *   export const TOOL_RENDERERS: Record<string, ComponentType<ToolRendererProps>> = {
 *     saveArtifact: ArtifactLinkCard,
 *     getWeather: WeatherCard,
 *   };
 */
export const TOOL_RENDERERS: Record<
  string,
  ComponentType<ToolRendererProps>
> = {
  saveArtifact: ArtifactLinkCard,
};

export function getToolRenderer(
  toolName: string
): ComponentType<ToolRendererProps> {
  return TOOL_RENDERERS[toolName] ?? DefaultToolCard;
}

/** Maps a tool part's state to its `chat.toolCard.*` message key. */
const STATE_MESSAGE_KEY: Record<ToolPartState, string> = {
  "input-streaming": "toolCard.calling",
  "input-available": "toolCard.running",
  "approval-requested": "toolCard.needsApproval",
  "approval-responded": "toolCard.approved",
  "output-available": "toolCard.done",
  "output-error": "toolCard.error",
  "output-denied": "toolCard.denied",
};

function toolLabel(toolName: string): string {
  const spaced = toolName.replace(/([a-z0-9])([A-Z])/g, "$1 $2");
  return spaced.charAt(0).toUpperCase() + spaced.slice(1).toLowerCase();
}

export function DefaultToolCard({
  toolName,
  state,
  input,
  output,
  errorText,
}: ToolRendererProps) {
  const t = useTranslations("chat");
  const [open, setOpen] = useState(false);

  return (
    <div className="max-w-[85%] rounded-lg border bg-muted/30 text-sm">
      <button
        type="button"
        onClick={() => setOpen((value) => !value)}
        className="flex w-full items-center gap-2 px-3 py-2 text-left"
      >
        {open ? (
          <ChevronDown className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
        ) : (
          <ChevronRight className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
        )}
        <Wrench className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
        <span className="font-medium">{toolLabel(toolName)}</span>
        <span className="ml-auto shrink-0 text-xs text-muted-foreground">
          {t(STATE_MESSAGE_KEY[state])}
        </span>
      </button>
      {open ? (
        <div className="space-y-2 border-t px-3 py-2">
          {input !== undefined ? (
            <pre className="overflow-x-auto whitespace-pre-wrap break-words text-xs text-muted-foreground">
              {JSON.stringify(input, null, 2)}
            </pre>
          ) : null}
          {output !== undefined ? (
            <pre className="overflow-x-auto whitespace-pre-wrap break-words text-xs">
              {JSON.stringify(output, null, 2)}
            </pre>
          ) : null}
          {errorText ? (
            <p className="text-xs text-destructive">{errorText}</p>
          ) : null}
        </div>
      ) : null}
    </div>
  );
}

/**
 * Renderer for a tool that produced a document artifact. Expects the
 * tool's output to carry a `title` (and optionally a `documentId`);
 * anything else falls back to the generic card, so a tool whose shape
 * drifts renders honestly rather than blank.
 *
 * This is the chat↔artifacts affordance: a reply that generated a
 * document says so inline, and links to where the document lives.
 */
export function ArtifactLinkCard({
  toolName,
  state,
  input,
  output,
  errorText,
}: ToolRendererProps) {
  const t = useTranslations("chat");

  const title =
    output && typeof output === "object" && "title" in output
      ? String((output as { title: unknown }).title)
      : undefined;

  if (state !== "output-available" || !title) {
    return (
      <DefaultToolCard
        toolName={toolName}
        state={state}
        input={input}
        output={output}
        errorText={errorText}
      />
    );
  }

  return (
    <div className="flex max-w-[85%] items-center gap-3 rounded-lg border bg-muted/30 px-3 py-2 text-sm">
      <FileText className="h-4 w-4 shrink-0 text-muted-foreground" />
      <div className="min-w-0 flex-1">
        <p className="truncate font-medium">{title}</p>
        <p className="text-xs text-muted-foreground">
          {t("artifactCard.saved")}
        </p>
      </div>
      <Link
        href="/artifacts"
        className="shrink-0 text-xs font-medium text-primary hover:underline"
      >
        {t("artifactCard.open")}
      </Link>
    </div>
  );
}

"use client";

/**
 * Chat — client root. Owns streaming state via the AI SDK's `useChat`
 * (`@ai-sdk/react`), talking to `app/api/chat/route.ts` over a
 * `DefaultChatTransport`. `initialMessages` comes from the server
 * component (`app/[locale]/(app)/chat/[id]/page.tsx`, via
 * `@/actions/chat`) so reloading a conversation shows its history
 * immediately, with no client-side fetch-on-mount.
 *
 * A `?query=` search param seeds the first turn: another surface (the
 * dashboard's prompt bar, a marketing CTA) can mint a conversation id
 * and link straight into a started conversation. It is sent once, only
 * into an empty conversation, so a refresh doesn't replay it.
 */

import { useEffect, useMemo, useRef } from "react";
import { useTranslations } from "next-intl";
import { DefaultChatTransport } from "ai";
import { useChat } from "@ai-sdk/react";
import type { UIMessage } from "ai";
import { useSearchParams } from "next/navigation";

import { ChatInput } from "./chat-input";
import { MessageList } from "./message-list";
import { chatConfig } from "@/lib/chat-config";
import type { ToolRendererActions } from "@/lib/chat-renderers";

interface ChatProps {
  conversationId: string;
  initialMessages: UIMessage[];
}

export function Chat({ conversationId, initialMessages }: ChatProps) {
  const t = useTranslations("chat");
  // Namespace-less: `chatConfig.starters` entries are fully-qualified
  // message keys into the app's whole message tree (see
  // `@/lib/chat-config`'s doc comment), not keys under this item's own
  // "chat" namespace.
  const tAny = useTranslations();
  const searchParams = useSearchParams();

  const transport = useMemo(
    () =>
      new DefaultChatTransport({
        api: "/api/chat",
        body: { id: conversationId },
      }),
    [conversationId]
  );

  const {
    messages,
    sendMessage,
    regenerate,
    addToolResult,
    status,
    stop,
    error,
  } = useChat({
    id: conversationId,
    messages: initialMessages,
    transport,
    sendAutomaticallyWhen: chatConfig.sendAutomaticallyWhen,
  });

  const isStreaming = status === "streaming" || status === "submitted";

  const starters = useMemo(
    () => (chatConfig.starters ?? []).map((key) => tAny(key)),
    [tAny]
  );

  function friendlyChatError(chatError: Error): string {
    try {
      const parsed = JSON.parse(chatError.message) as { error?: string };
      if (parsed.error) return parsed.error;
    } catch {
      // Not JSON — the transport surfaces the raw response text on a
      // non-JSON error response.
    }
    return chatError.message || t("error.generic");
  }

  function handleSend(text: string) {
    if (!text.trim() || isStreaming) return;
    void sendMessage({ text });
  }

  // Prefill from `?query=`, once, and only into a conversation that has
  // no messages yet.
  const prefillSent = useRef(false);
  useEffect(() => {
    if (prefillSent.current) return;
    const query = searchParams.get("query");
    if (!query || messages.length > 0) return;
    prefillSent.current = true;
    void sendMessage({ text: query });
  }, [searchParams, messages.length, sendMessage]);

  // Rebuilt each render on purpose: `handleSend` closes over
  // `isStreaming`, and nothing downstream is memoized on this object.
  const toolActions: ToolRendererActions = {
    sendMessage: handleSend,
    addToolResult: (args) => void addToolResult(args),
  };

  return (
    <div className="flex min-h-0 flex-1 flex-col">
      <MessageList
        messages={messages}
        isStreaming={status === "streaming"}
        starters={starters}
        onStarterSelect={handleSend}
        onRetry={isStreaming ? undefined : () => void regenerate()}
        toolActions={toolActions}
      />
      {error ? (
        <div
          role="alert"
          className="mx-auto mb-2 w-full max-w-3xl rounded-md border border-destructive/40 bg-destructive/10 px-4 py-2 text-sm text-destructive"
        >
          {friendlyChatError(error)}
        </div>
      ) : null}
      <ChatInput onSend={handleSend} onStop={stop} isStreaming={isStreaming} />
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";
import { useTranslations } from "next-intl";
import type { UIMessage } from "ai";

import { Button } from "@/components/ui/button";
import type { ToolRendererActions } from "@/lib/chat-renderers";
import { Message } from "./message";

interface MessageListProps {
  messages: UIMessage[];
  isStreaming: boolean;
  /** Resolved starter prompt text — see `@/lib/chat-config`. */
  starters?: string[];
  /** Called with a starter's text when the caller picks one. */
  onStarterSelect?: (text: string) => void;
  /** Regenerate the last assistant reply; omit to hide the control. */
  onRetry?: () => void;
  /** Passed to interactive tool renderers — see `@/lib/chat-renderers`. */
  toolActions?: ToolRendererActions;
}

export function MessageList({
  messages,
  isStreaming,
  starters,
  onStarterSelect,
  onRetry,
  toolActions,
}: MessageListProps) {
  const bottomRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth", block: "end" });
  }, [messages.length, isStreaming]);

  if (messages.length === 0) {
    return <EmptyState starters={starters} onStarterSelect={onStarterSelect} />;
  }

  return (
    <div className="flex-1 overflow-y-auto px-4 py-6">
      <div className="mx-auto flex max-w-3xl flex-col gap-6">
        {messages.map((message, index) => (
          <Message
            key={message.id}
            message={message}
            isLastMessage={index === messages.length - 1}
            isStreaming={isStreaming}
            onRetry={onRetry}
            toolActions={toolActions}
          />
        ))}
        <div ref={bottomRef} />
      </div>
    </div>
  );
}

function EmptyState({
  starters,
  onStarterSelect,
}: {
  starters?: string[];
  onStarterSelect?: (text: string) => void;
}) {
  const t = useTranslations("chat");

  return (
    <div className="flex flex-1 flex-col items-center justify-center gap-4 px-4 text-center">
      <div className="space-y-2">
        <h2 className="text-lg font-semibold">{t("emptyState.title")}</h2>
        <p className="max-w-sm text-sm text-muted-foreground">
          {t("emptyState.description")}
        </p>
      </div>
      {starters && starters.length > 0 ? (
        <div className="flex max-w-2xl flex-wrap justify-center gap-2">
          {starters.map((starter, index) => (
            <Button
              key={index}
              type="button"
              variant="outline"
              size="sm"
              className="h-auto whitespace-normal rounded-full px-4 py-2 text-left text-sm"
              onClick={() => onStarterSelect?.(starter)}
            >
              {starter}
            </Button>
          ))}
        </div>
      ) : null}
    </div>
  );
}

"use client";

/**
 * Renders one `UIMessage`'s parts. Text uses `streamdown` (the same
 * markdown-while-streaming renderer the dissolving `@intelligo-dev/chat`
 * package used) rather than a plain `<pre>` — chat replies are
 * routinely lists, code blocks and headings, and re-parsing a partial
 * markdown document on every token is exactly the incremental-parsing
 * problem that package exists to solve. Tool parts are handed to
 * `@/lib/chat-renderers`'s seam; reasoning parts get a plain
 * collapsible `<details>` (no product ships a "thinking" design by
 * default, so this stays undecorated on purpose).
 *
 * A finished assistant message carries an action row — copy the reply,
 * regenerate it (last message only), and save it as an artifact so the
 * `artifacts` item's page has something to show. The row is hidden
 * while that message is still streaming.
 */

import { useState, useTransition } from "react";
import { getToolName, isReasoningUIPart, isTextUIPart, isToolUIPart } from "ai";
import type { UIMessage } from "ai";
import { useTranslations } from "next-intl";
import { Bot, Check, Copy, FileDown, RefreshCw, User } from "lucide-react";
import { Streamdown } from "streamdown";
import { toast } from "sonner";

import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import {
  getToolRenderer,
  type ToolRendererActions,
} from "@/lib/chat-renderers";
import { saveMessageAsArtifact } from "@/actions/chat";

interface MessageProps {
  message: UIMessage;
  isLastMessage: boolean;
  isStreaming: boolean;
  /** Regenerate the last assistant reply; omit to hide the control. */
  onRetry?: () => void;
  toolActions?: ToolRendererActions;
}

/** The message's plain text, for copying and for artifact content. */
function messageText(message: UIMessage): string {
  return message.parts
    .filter(isTextUIPart)
    .map((part) => part.text)
    .join("\n\n")
    .trim();
}

export function Message({
  message,
  isLastMessage,
  isStreaming,
  onRetry,
  toolActions,
}: MessageProps) {
  const t = useTranslations("chat");
  const isUser = message.role === "user";
  const isEmptyAssistant =
    !isUser && message.parts.every((part) => !isTextUIPart(part) || !part.text);
  const isStreamingThis = isLastMessage && isStreaming;
  const text = messageText(message);
  const showActions = !isUser && !isStreamingThis && text.length > 0;

  return (
    <div className={cn("group flex gap-3", isUser && "flex-row-reverse")}>
      <div
        className={cn(
          "flex h-7 w-7 shrink-0 items-center justify-center rounded-full",
          isUser ? "bg-primary text-primary-foreground" : "bg-muted"
        )}
      >
        {isUser ? <User className="h-4 w-4" /> : <Bot className="h-4 w-4" />}
      </div>

      <div
        className={cn(
          "min-w-0 flex-1 space-y-2",
          isUser && "flex flex-col items-end"
        )}
      >
        {message.parts.map((part, index) => {
          const key = `${message.id}-${index}`;

          if (isTextUIPart(part)) {
            if (!part.text) return null;
            return isUser ? (
              <div
                key={key}
                className="max-w-[85%] whitespace-pre-wrap rounded-2xl bg-primary px-4 py-2 text-sm text-primary-foreground"
              >
                {part.text}
              </div>
            ) : (
              <div
                key={key}
                className="max-w-[85%] text-sm leading-relaxed [&_pre]:overflow-x-auto"
              >
                <Streamdown>{part.text}</Streamdown>
              </div>
            );
          }

          if (isReasoningUIPart(part)) {
            if (!part.text) return null;
            return (
              <details
                key={key}
                className="max-w-[85%] rounded-md border bg-muted/30 px-3 py-2 text-xs text-muted-foreground"
              >
                <summary className="cursor-pointer select-none">
                  {t("message.reasoning")}
                </summary>
                <div className="mt-2 whitespace-pre-wrap">{part.text}</div>
              </details>
            );
          }

          if (isToolUIPart(part)) {
            const toolName = getToolName(part);
            const Renderer = getToolRenderer(toolName);
            const state = part.state;
            return (
              <Renderer
                key={key}
                toolName={toolName}
                state={state}
                input={"input" in part ? part.input : undefined}
                output={state === "output-available" ? part.output : undefined}
                errorText={
                  state === "output-error" ? part.errorText : undefined
                }
                toolCallId={"toolCallId" in part ? part.toolCallId : undefined}
                actions={toolActions}
              />
            );
          }

          return null;
        })}

        {isStreamingThis && isEmptyAssistant ? (
          <span
            className="inline-block h-4 w-1.5 animate-pulse rounded-full bg-muted-foreground/50"
            aria-hidden
          />
        ) : null}

        {showActions ? (
          <MessageActions
            text={text}
            messageId={message.id}
            onRetry={isLastMessage ? onRetry : undefined}
          />
        ) : null}
      </div>
    </div>
  );
}

function MessageActions({
  text,
  messageId,
  onRetry,
}: {
  text: string;
  messageId: string;
  onRetry?: () => void;
}) {
  const t = useTranslations("chat");
  const [copied, setCopied] = useState(false);
  const [isSaving, startSaving] = useTransition();

  async function handleCopy() {
    try {
      await navigator.clipboard.writeText(text);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      toast.error(t("actions.copyFailed"));
    }
  }

  function handleSave() {
    startSaving(async () => {
      const result = await saveMessageAsArtifact({ messageId, content: text });
      if (result.success) {
        toast.success(t("actions.savedToArtifacts"));
      } else {
        toast.error(result.error);
      }
    });
  }

  return (
    <div className="flex items-center gap-1 opacity-0 transition-opacity focus-within:opacity-100 group-hover:opacity-100">
      <Button
        type="button"
        variant="ghost"
        size="sm"
        className="h-7 gap-1.5 px-2 text-xs text-muted-foreground"
        onClick={handleCopy}
      >
        {copied ? (
          <Check className="h-3.5 w-3.5" />
        ) : (
          <Copy className="h-3.5 w-3.5" />
        )}
        {copied ? t("actions.copied") : t("actions.copy")}
      </Button>

      {onRetry ? (
        <Button
          type="button"
          variant="ghost"
          size="sm"
          className="h-7 gap-1.5 px-2 text-xs text-muted-foreground"
          onClick={onRetry}
        >
          <RefreshCw className="h-3.5 w-3.5" />
          {t("actions.retry")}
        </Button>
      ) : null}

      <Button
        type="button"
        variant="ghost"
        size="sm"
        className="h-7 gap-1.5 px-2 text-xs text-muted-foreground"
        onClick={handleSave}
        disabled={isSaving}
      >
        <FileDown className="h-3.5 w-3.5" />
        {t("actions.save")}
      </Button>
    </div>
  );
}

"use client";

import { useState } from "react";
import type { KeyboardEvent } from "react";
import { useTranslations } from "next-intl";
import { ArrowUp, Square } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";

interface ChatInputProps {
  onSend: (text: string) => void;
  onStop: () => void;
  isStreaming: boolean;
}

export function ChatInput({ onSend, onStop, isStreaming }: ChatInputProps) {
  const t = useTranslations("chat");
  const [value, setValue] = useState("");

  function submit() {
    const text = value.trim();
    if (!text || isStreaming) return;
    onSend(text);
    setValue("");
  }

  function handleKeyDown(event: KeyboardEvent<HTMLTextAreaElement>) {
    if (event.key === "Enter" && !event.shiftKey) {
      event.preventDefault();
      submit();
    }
  }

  return (
    <div className="border-t bg-background px-4 py-3">
      <div className="mx-auto flex max-w-3xl items-end gap-2">
        <Textarea
          value={value}
          onChange={(event) => setValue(event.target.value)}
          onKeyDown={handleKeyDown}
          placeholder={t("input.placeholder")}
          rows={1}
          className="max-h-40 min-h-10 flex-1 resize-none"
        />
        {isStreaming ? (
          <Button
            type="button"
            size="icon"
            variant="outline"
            onClick={onStop}
            aria-label={t("input.stop")}
          >
            <Square className="h-4 w-4" />
          </Button>
        ) : (
          <Button
            type="button"
            size="icon"
            onClick={submit}
            disabled={!value.trim()}
            aria-label={t("input.send")}
          >
            <ArrowUp className="h-4 w-4" />
          </Button>
        )}
      </div>
    </div>
  );
}

"use client";

/**
 * Conversation header — title with inline rename, a history dropdown
 * for switching conversations, a "New chat" link, and delete.
 *
 * The history dropdown and "New chat" here are the small-screen
 * controls: from `lg` up, `ConversationSidebar` shows the same list
 * permanently and both are hidden rather than duplicated.
 */

import { useState, useTransition } from "react";
import { useTranslations } from "next-intl";
import {
  Check,
  ChevronDown,
  Loader2,
  Pencil,
  Plus,
  Trash2,
  X,
} from "lucide-react";
import { toast } from "sonner";

import { Link, useRouter } from "@/i18n/navigation";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Input } from "@/components/ui/input";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";

import { deleteConversation, renameConversation } from "@/actions/chat";
import type { ConversationSummary } from "@/actions/chat";
import { chatConfig } from "@/lib/chat-config";

interface ConversationHeaderProps {
  conversationId: string;
  title: string | null;
  history: ConversationSummary[];
}

export function ConversationHeader({
  conversationId,
  title,
  history,
}: ConversationHeaderProps) {
  const t = useTranslations("chat");
  const router = useRouter();
  const [isPending, startTransition] = useTransition();
  const [isEditing, setIsEditing] = useState(false);
  const [draftTitle, setDraftTitle] = useState(title ?? "");
  const HeaderRight = chatConfig.headerRight;
  const agentName = chatConfig.agent?.name ?? t("agent.defaultName");
  const agentIcon = chatConfig.agent?.icon;

  function startEditing() {
    setDraftTitle(title ?? "");
    setIsEditing(true);
  }

  function commitRename() {
    const trimmed = draftTitle.trim();
    setIsEditing(false);
    if (!trimmed || trimmed === title) return;

    startTransition(async () => {
      const result = await renameConversation(conversationId, trimmed);
      if (!result.success) {
        toast.error(result.error);
        return;
      }
      router.refresh();
    });
  }

  function handleDelete() {
    startTransition(async () => {
      const result = await deleteConversation(conversationId);
      if (!result.success) {
        toast.error(result.error);
        return;
      }
      router.push("/chat");
    });
  }

  return (
    <header className="flex items-center justify-between gap-2 border-b px-4 py-3">
      <div className="flex min-w-0 flex-1 items-center gap-1">
        <span className="mr-1 flex shrink-0 items-center gap-1 text-xs text-muted-foreground">
          {agentIcon ? <span aria-hidden>{agentIcon}</span> : null}
          <span className="max-w-24 truncate">{agentName}</span>
        </span>
        {isEditing ? (
          <>
            <Input
              autoFocus
              value={draftTitle}
              onChange={(event) => setDraftTitle(event.target.value)}
              onKeyDown={(event) => {
                if (event.key === "Enter") commitRename();
                if (event.key === "Escape") setIsEditing(false);
              }}
              className="h-8 max-w-xs"
            />
            <Button
              size="icon"
              variant="ghost"
              className="h-8 w-8 shrink-0"
              onClick={commitRename}
              aria-label={t("header.renameSave")}
            >
              <Check className="h-4 w-4" />
            </Button>
            <Button
              size="icon"
              variant="ghost"
              className="h-8 w-8 shrink-0"
              onClick={() => setIsEditing(false)}
              aria-label={t("header.renameCancel")}
            >
              <X className="h-4 w-4" />
            </Button>
          </>
        ) : (
          <>
            <h1 className="truncate text-sm font-medium">
              {title || t("header.newChatTitle")}
            </h1>
            <Button
              size="icon"
              variant="ghost"
              className="h-7 w-7 shrink-0"
              onClick={startEditing}
              aria-label={t("header.renameEdit")}
            >
              <Pencil className="h-3.5 w-3.5" />
            </Button>
          </>
        )}
      </div>

      <div className="flex shrink-0 items-center gap-2">
        {HeaderRight ? <HeaderRight conversationId={conversationId} /> : null}

        {/* Below `lg` this is the only way to reach history; at `lg`
            and up `ConversationSidebar` shows the same list. */}
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="outline" size="sm" className="gap-1 lg:hidden">
              {t("header.historyTrigger")}
              <ChevronDown className="h-3.5 w-3.5" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="w-64">
            {history.length === 0 ? (
              <div className="px-2 py-1.5 text-sm text-muted-foreground">
                {t("header.historyEmpty")}
              </div>
            ) : (
              history.map((item) => (
                <DropdownMenuItem key={item.id} asChild>
                  <Link href={`/chat/${item.id}`} className="truncate">
                    {item.title || t("header.historyUntitled")}
                  </Link>
                </DropdownMenuItem>
              ))
            )}
          </DropdownMenuContent>
        </DropdownMenu>

        <Button variant="outline" size="sm" asChild className="lg:hidden">
          <Link href="/chat">
            <Plus className="mr-1 h-3.5 w-3.5" />
            {t("header.newChat")}
          </Link>
        </Button>

        {/* Confirmed: deleting a conversation is unrecoverable, and
            this control sits one pixel from "New chat". */}
        <AlertDialog>
          <AlertDialogTrigger asChild>
            <Button
              variant="ghost"
              size="icon"
              className="h-8 w-8 text-muted-foreground hover:text-destructive"
              disabled={isPending}
              aria-label={t("header.delete")}
            >
              {isPending ? (
                <Loader2 className="h-4 w-4 animate-spin" />
              ) : (
                <Trash2 className="h-4 w-4" />
              )}
            </Button>
          </AlertDialogTrigger>
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>{t("deleteDialog.title")}</AlertDialogTitle>
              <AlertDialogDescription>
                {t("deleteDialog.description")}
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel>{t("deleteDialog.cancel")}</AlertDialogCancel>
              <AlertDialogAction onClick={handleDelete}>
                {t("deleteDialog.confirm")}
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      </div>
    </header>
  );
}

"use client";

/**
 * Persistent conversation history beside the chat.
 *
 * The header's dropdown was fine while a workspace had a handful of
 * conversations and stopped being fine somewhere around thirty: no
 * search, no sense of when anything happened, and the current
 * conversation invisible in the list. This puts history where a chat
 * product keeps it — always on screen, grouped by recency, filterable.
 *
 * Below `lg` it is hidden and the header's dropdown takes over: a
 * fixed sidebar on a phone costs more than it returns, and the two
 * controls read the same data, so nothing is lost.
 *
 * Filtering is client-side over what the server already sent. That is
 * honest for the sizes this list actually reaches; a workspace with
 * thousands of conversations wants a server-side search action, and
 * this component's props are shaped so adding one later replaces the
 * filter without touching the layout.
 */

import { useMemo, useState } from "react";
import { MessageSquare, Plus, Search } from "lucide-react";
import { useTranslations } from "next-intl";

import { Link } from "@/i18n/navigation";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import type { ConversationSummary } from "@/actions/chat";

interface ConversationSidebarProps {
  conversations: ConversationSummary[];
  /** The conversation on screen, highlighted and never filtered out. */
  activeId: string;
}

type Bucket = "today" | "week" | "month" | "older";

const BUCKET_ORDER: Bucket[] = ["today", "week", "month", "older"];

function bucketFor(updatedAt: string, now: number): Bucket {
  const ageMs = now - new Date(updatedAt).getTime();
  const day = 24 * 60 * 60 * 1000;
  if (ageMs < day) return "today";
  if (ageMs < 7 * day) return "week";
  if (ageMs < 30 * day) return "month";
  return "older";
}

export function ConversationSidebar({
  conversations,
  activeId,
}: ConversationSidebarProps) {
  const t = useTranslations("chat");
  const [query, setQuery] = useState("");

  const grouped = useMemo(() => {
    const needle = query.trim().toLowerCase();
    // `Date.now()` inside the memo, not during render, keeps the
    // bucket boundaries stable for a given filter pass.
    const now = Date.now();

    const matches = conversations.filter((conversation) => {
      if (!needle) return true;
      return (conversation.title ?? "").toLowerCase().includes(needle);
    });

    const buckets = new Map<Bucket, ConversationSummary[]>();
    for (const conversation of matches) {
      const bucket = bucketFor(conversation.updatedAt, now);
      buckets.set(bucket, [...(buckets.get(bucket) ?? []), conversation]);
    }
    return buckets;
  }, [conversations, query]);

  const empty = BUCKET_ORDER.every((bucket) => !grouped.get(bucket)?.length);

  return (
    <aside className="hidden w-64 shrink-0 flex-col border-r lg:flex">
      <div className="space-y-2 border-b p-3">
        <Button asChild size="sm" className="w-full justify-start gap-2">
          <Link href="/chat">
            <Plus className="h-3.5 w-3.5" />
            {t("header.newChat")}
          </Link>
        </Button>

        <div className="relative">
          <Search
            className="absolute left-2.5 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-muted-foreground"
            aria-hidden
          />
          <Input
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder={t("sidebar.searchPlaceholder")}
            aria-label={t("sidebar.searchPlaceholder")}
            className="h-8 pl-8 text-sm"
          />
        </div>
      </div>

      <nav
        aria-label={t("sidebar.label")}
        className="flex-1 overflow-y-auto px-2 py-3"
      >
        {empty ? (
          <p className="px-2 text-sm text-muted-foreground">
            {query ? t("sidebar.noMatches") : t("header.historyEmpty")}
          </p>
        ) : (
          BUCKET_ORDER.map((bucket) => {
            const items = grouped.get(bucket);
            if (!items?.length) return null;
            return (
              <div key={bucket} className="mb-4">
                <p className="px-2 pb-1 text-xs font-medium uppercase tracking-wide text-muted-foreground">
                  {t(`sidebar.groups.${bucket}`)}
                </p>
                <ul>
                  {items.map((conversation) => {
                    const isActive = conversation.id === activeId;
                    return (
                      <li key={conversation.id}>
                        <Link
                          href={`/chat/${conversation.id}`}
                          aria-current={isActive ? "page" : undefined}
                          className={`flex items-center gap-2 rounded-md px-2 py-1.5 text-sm transition-colors ${
                            isActive
                              ? "bg-accent font-medium"
                              : "hover:bg-accent/50"
                          }`}
                          title={
                            conversation.title ?? t("header.historyUntitled")
                          }
                        >
                          <MessageSquare
                            className="h-3.5 w-3.5 shrink-0 text-muted-foreground"
                            aria-hidden
                          />
                          <span className="truncate">
                            {conversation.title ?? t("header.historyUntitled")}
                          </span>
                        </Link>
                      </li>
                    );
                  })}
                </ul>
              </div>
            );
          })
        )}
      </nav>

      <p className="border-t px-3 py-2 text-xs text-muted-foreground">
        {t("sidebar.count", { count: conversations.length })}
      </p>
    </aside>
  );
}

